  ('3f9faa74-96ff-4f35-b3ab-03ca0faf34d6', '9a7e196b-3718-4287-a5cd-3d32a7de093c', 12,
   '[{"domain": "Golven", "subdomain": "Informatieoverdracht"}]'::jsonb,
